CREATE SCHEMA IF NOT EXISTS tran;
SET search_path TO tran, public;
CREATE TABLE IF NOT EXISTS organization (id BIGSERIAL PRIMARY KEY, name VARCHAR(180) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS office (id BIGSERIAL PRIMARY KEY, organization_id BIGINT REFERENCES organization(id), name VARCHAR(180) NOT NULL);
CREATE TABLE IF NOT EXISTS department (id BIGSERIAL PRIMARY KEY, office_id BIGINT REFERENCES office(id), name VARCHAR(180) NOT NULL UNIQUE, code VARCHAR(30));
CREATE TABLE IF NOT EXISTS employee_details (id BIGSERIAL PRIMARY KEY, employee_code VARCHAR(40) UNIQUE NOT NULL, first_name VARCHAR(80) NOT NULL, middle_name VARCHAR(80), last_name VARCHAR(80) NOT NULL, gender VARCHAR(20), date_of_birth DATE, department_id BIGINT REFERENCES department(id), designation VARCHAR(120), mobile VARCHAR(10), email VARCHAR(180) UNIQUE NOT NULL, active BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS user_account (id BIGSERIAL PRIMARY KEY, employee_id BIGINT UNIQUE REFERENCES employee_details(id) ON DELETE CASCADE, email VARCHAR(180) UNIQUE NOT NULL, password_hash VARCHAR(100) NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('EMPLOYEE','AUTHORITY')), enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS acr_cycle (id BIGSERIAL PRIMARY KEY, assessment_year VARCHAR(9) NOT NULL UNIQUE, due_date DATE NOT NULL, is_open BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_acr_status (id BIGSERIAL PRIMARY KEY, employee_id BIGINT NOT NULL REFERENCES employee_details(id), cycle_id BIGINT NOT NULL REFERENCES acr_cycle(id), assessment_year VARCHAR(9) NOT NULL, requested BOOLEAN NOT NULL DEFAULT FALSE, requested_at TIMESTAMPTZ, submitted BOOLEAN NOT NULL DEFAULT FALSE, status VARCHAR(30) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','SUBMITTED','APPROVED','REJECTED','NEEDS_RESUBMISSION')), grade VARCHAR(20), remark TEXT, flagged BOOLEAN NOT NULL DEFAULT FALSE, resubmission_reason TEXT, revision INTEGER NOT NULL DEFAULT 0, submitted_at TIMESTAMPTZ, reviewed_at TIMESTAMPTZ, UNIQUE(employee_id, assessment_year));
CREATE TABLE IF NOT EXISTS employee_acr_details (id BIGSERIAL PRIMARY KEY, acr_status_id BIGINT NOT NULL REFERENCES employee_acr_status(id) ON DELETE CASCADE, target TEXT NOT NULL, achievement TEXT NOT NULL, sequence_no INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS notification (id BIGSERIAL PRIMARY KEY, recipient_employee_id BIGINT NOT NULL REFERENCES employee_details(id) ON DELETE CASCADE, type VARCHAR(40) NOT NULL, title VARCHAR(180) NOT NULL, message TEXT NOT NULL, read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS acr_audit (id BIGSERIAL PRIMARY KEY, acr_status_id BIGINT NOT NULL REFERENCES employee_acr_status(id), actor_user_id BIGINT REFERENCES user_account(id), action VARCHAR(60) NOT NULL, details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS acr_submission_history (id BIGSERIAL PRIMARY KEY, acr_status_id BIGINT NOT NULL REFERENCES employee_acr_status(id), revision INTEGER NOT NULL, snapshot JSONB NOT NULL, submitted_by BIGINT REFERENCES user_account(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(acr_status_id, revision));
CREATE INDEX IF NOT EXISTS idx_employee_dept ON employee_details(department_id);
CREATE INDEX IF NOT EXISTS idx_acr_status_year ON employee_acr_status(assessment_year,status);
CREATE INDEX IF NOT EXISTS idx_notification_recipient ON notification(recipient_employee_id,read,created_at DESC);
CREATE OR REPLACE FUNCTION tran.reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit and submission history rows are immutable'; END $$;
DROP TRIGGER IF EXISTS acr_audit_immutable ON acr_audit;
CREATE TRIGGER acr_audit_immutable BEFORE UPDATE OR DELETE ON acr_audit FOR EACH ROW EXECUTE FUNCTION tran.reject_immutable_change();
DROP TRIGGER IF EXISTS acr_history_immutable ON acr_submission_history;
CREATE TRIGGER acr_history_immutable BEFORE UPDATE OR DELETE ON acr_submission_history FOR EACH ROW EXECUTE FUNCTION tran.reject_immutable_change();

CREATE UNIQUE INDEX IF NOT EXISTS uq_acr_cycle_single_open ON tran.acr_cycle(is_open) WHERE is_open = TRUE;
